function parseObject(value) {
  if (typeof value === 'string') {
    const text = value.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    value = JSON.parse(text);
  }
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Expected a JSON object');
  return value;
}
function researchValidate(ctx, raw) {
  const report = parseObject(raw.choices?.[0]?.message?.content ?? raw);
  if (!Array.isArray(report.posts) || !Array.isArray(report.articles)) throw new Error('Hermes must return posts and articles arrays');
  const now = Date.now(), cutoff = now - ctx.lookbackHours * 3600000;
  const selected = [], rejected = [], seen = new Set(), authors = new Set();
  const validDate = x => typeof x === 'string' && /T.*(?:Z|[+-]\d\d:\d\d)$/.test(x) && Number.isFinite(Date.parse(x));
  const postPattern = /^https:\/\/x\.com\/[A-Za-z0-9_]+\/status\/\d+(?:\?.*)?$/;
  const articlePattern = /^https:\/\/x\.com\/i\/article\/\d+(?:\?.*)?$/;
  for (const [kind, list] of [['post', report.posts], ['article', report.articles]]) {
    let count = 0;
    if (list.length > 30) throw new Error('Candidate limit exceeded');
    for (const p of list) {
      let reason = '';
      const evidenceDate = kind === 'article' && p.resharedAt ? p.resharedAt : p.publishedAt;
      const id = String(p.url || '').split('?')[0];
      if (!postPattern.test(p.url || '')) reason = 'missing_or_invalid_source_post';
      else if (!ctx.demo && p.synthetic === true) reason = 'synthetic_live_input';
      else if (!validDate(p.publishedAt) || !validDate(evidenceDate) || Date.parse(evidenceDate) < cutoff || Date.parse(evidenceDate) > now + 60000) reason = 'outside_window_or_missing_date';
      else if (kind === 'article' && (!articlePattern.test(p.articleUrl || '') || !p.articleSummary)) reason = 'missing_native_article_or_article_summary';
      else if (!Array.isArray(p.citations) || !p.citations.includes(p.url) || (kind === 'article' && !p.citations.includes(p.articleUrl))) reason = 'missing_citation';
      else if (!(Number.isInteger(p.likes) && p.likes >= ctx.minLikes || Number.isInteger(p.reposts) && p.reposts >= ctx.minReposts)) reason = 'missing_or_below_reported_engagement';
      else if (!p.author || !p.summary || !Number.isFinite(p.score) || p.score < ctx.minScore || p.score > 100) reason = 'missing_summary_or_below_score';
      else if (seen.has(id) || authors.has(p.author)) reason = 'duplicate_source_or_author';
      else if (count >= ctx.maxPerKind) reason = 'category_limit';
      if (reason) { rejected.push({kind, url:p.url || null, reason}); continue; }
      count++; seen.add(id); authors.add(p.author);
      const summary = String(kind === 'article' ? p.articleSummary : p.summary).replace(/@/g, '@\u200b').slice(0, 650);
      selected.push({kind, sourceUrl:p.url, articleUrl:kind === 'article' ? p.articleUrl : null, publishedAt:p.publishedAt, resurfacedAt:p.resharedAt || null,
        summary, score:p.score, reportedLikes:p.likes ?? null, reportedReposts:p.reposts ?? null,
        evidenceStatus:ctx.demo ? 'synthetic_demo' : 'Hermes_reported_not_independently_verified',
        notification:`${kind === 'article' ? 'X article' : 'X post'}\n${summary}\n${p.url}${kind === 'article' ? '\n'+p.articleUrl : ''}\nSource date: ${p.publishedAt}${p.resharedAt ? '\nReshared: '+p.resharedAt : ''}\nEngagement reported by Hermes; not independently verified.`});
    }
