  return {status:ctx.demo ? 'demo_complete' : selected.length ? 'candidates_ready' : 'no_eligible_candidates', selected, rejected,
    counts:{posts:selected.filter(x=>x.kind==='post').length,articles:selected.filter(x=>x.kind==='article').length},
    notice:'URL syntax and reported fields are checked. This does not independently confirm X post existence or popularity. Deduplication covers this run only.'};
}
function platformNormalize(raw) {
  const x=parseObject(raw.output ?? raw.data?.modelResponse ?? raw.current ?? raw);
