  const dates=x.dates.map(d=> {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(d.date || '') || new Date(d.date+'T00:00:00Z').toISOString().slice(0,10)!==d.date || !/^\d\d:\d\d$/.test(d.time || '') || +d.time.slice(0,2)>23 || +d.time.slice(3)>59 || !Number.isInteger(d.capacity) || d.capacity<0) throw new Error('Invalid date, time or capacity');
    return {date:d.date,time:d.time,capacity:d.capacity};
  }).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
  if (new Set(dates.map(d=>d.date+' '+d.time)).size!==dates.length) throw new Error('Duplicate date slot');
  if (x.title.length>200 || x.description.length>10000 || dates.length>30) throw new Error('Listing input exceeds size limits');
