function videoManifest(raw) {
  const m=parseObject(raw.manifest ?? raw);
  if (!m.projectName || typeof m.projectName!=='string' || m.projectName.length>100) throw new Error('Invalid project name');
  if (!Array.isArray(m.stageLabels) || m.stageLabels.length<2 || m.stageLabels.length>6 || m.stageLabels.some(x=>typeof x!=='string'||x.length>12)) throw new Error('Use 2-6 required stages');
  if (!Array.isArray(m.scenes) || m.scenes.length<2 || m.scenes.length>30) throw new Error('Use 2-30 scenes');
  const seen=new Set();let prev=-1;
  for (const s of m.scenes) {
    if (!/^[A-Za-z0-9_./-]+\.(?:png|jpe?g)$/i.test(s.image || '') || s.image.startsWith('/') || s.image.split('/').includes('..')) throw new Error('Use safe relative image filenames');
